import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";

const DATA_DIR = path.join(process.cwd(), "data");
const DATA_FILE = path.join(DATA_DIR, "books.json");

async function ensureFile() {
  await fs.mkdir(DATA_DIR, { recursive: true });
  try {
    await fs.access(DATA_FILE);
  } catch {
    await fs.writeFile(DATA_FILE, "[]\n", "utf8");
  }
}

async function readAll() {
  await ensureFile();
  const raw = await fs.readFile(DATA_FILE, "utf8");
  return JSON.parse(raw);
}

async function writeAll(books) {
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n", "utf8");
}

export async function getBooks() {
  return readAll();
}

export async function getBook(id) {
  const books = await readAll();
  return books.find((book) => book.id === id) ?? null;
}

export async function addBook({ title, author, notes }) {
  const books = await readAll();
  const book = {
    id: crypto.randomUUID(),
    title: title.trim(),
    author: author.trim(),
    notes: notes?.trim() ?? "",
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.unshift(book);
  await writeAll(books);
  return book;
}

export async function markFinished(id) {
  const books = await readAll();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await writeAll(books);
  return book;
}

