import Link from "next/link";
import { getBooks } from "@/lib/books";
import { addBookAction, markFinishedAction } from "@/app/actions";

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((book) => book.status === "reading");
  const finished = books.filter((book) => book.status === "finished");

  return (
    <main className="container">
      <h1>My Reading</h1>

      <section>
        <h2>Currently reading</h2>
        {reading.length === 0 ? (
          <p className="empty">Nothing yet — add a book below.</p>
        ) : (
          <ul className="book-list">
            {reading.map((book) => (
              <li key={book.id}>
                <Link href={`/books/${book.id}`}>{book.title}</Link>
                <span className="author"> by {book.author}</span>
                <form action={markFinishedAction} className="inline-form">
                  <input type="hidden" name="id" value={book.id} />
                  <button type="submit">Mark finished</button>
                </form>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Finished</h2>
        {finished.length === 0 ? (
          <p className="empty">No finished books yet.</p>
        ) : (
          <ul className="book-list">
            {finished.map((book) => (
              <li key={book.id}>
                <Link href={`/books/${book.id}`}>{book.title}</Link>
                <span className="author"> by {book.author}</span>
              </li>
            ))}
          </ul>
        )}
      </section>

      <section>
        <h2>Add a book</h2>
        <form action={addBookAction} className="add-form">
          <label>
            Title
            <input type="text" name="title" required />
          </label>
          <label>
            Author
            <input type="text" name="author" required />
          </label>
          <label>
            Notes
            <textarea name="notes" rows={3}></textarea>
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    </main>
  );
}

