import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "@/lib/books";
import { markFinishedAction } from "@/app/actions";

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);

  if (!book) {
    notFound();
  }

  return (
    <main className="container">
      <p>
        <Link href="/">← Back to my reading</Link>
      </p>

      <h1>{book.title}</h1>
      <p className="author">by {book.author}</p>
      <p className="status">
        {book.status === "reading" ? "Currently reading" : "Finished"}
      </p>

      {book.status === "reading" && (
        <form action={markFinishedAction}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit">Mark finished</button>
        </form>
      )}

      <h2>Notes</h2>
      <p className="notes">{book.notes || "No notes yet."}</p>
    </main>
  );
}

