* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
  color: #1a1a1a;
  background: #fafaf8;
}

.container {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1.5rem 4rem;
}

h1 {
  margin-bottom: 1.5rem;
}

section {
  margin-bottom: 2.5rem;
}

h2 {
  font-size: 1.1rem;
  border-bottom: 1px solid #e0e0dc;
  padding-bottom: 0.5rem;
}

.empty {
  color: #777;
  font-style: italic;
}

.book-list {
  list-style: none;
  padding: 0;
}

.book-list li {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  padding: 0.5rem 0;
  border-bottom: 1px solid #eee;
}

.book-list a {
  font-weight: 600;
  color: #1a1a1a;
  text-decoration: none;
}

.book-list a:hover {
  text-decoration: underline;
}

.author {
  color: #555;
}

.inline-form {
  margin-left: auto;
}

.add-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.add-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.9rem;
  color: #333;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 4px;
}

button {
  font: inherit;
  padding: 0.4rem 0.9rem;
  border: 1px solid #333;
  background: #1a1a1a;
  color: #fff;
  border-radius: 4px;
  cursor: pointer;
  width: fit-content;
}

button:hover {
  background: #333;
}

.status {
  color: #555;
}

.notes {
  white-space: pre-wrap;
}

